import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.*;
import org.json.*;

public class UserProfileServlet extends HttpServlet {
    private static final Pattern SAFE_FIELD_PATTERN = Pattern.compile("^[a-zA-Z_]+$");
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        dbUrl = System.getenv("DB_JDBC_URL");
        dbUser = System.getenv("DB_USER");
        dbPass = System.getenv("DB_PASS");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String userId = req.getParameter("user_id");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid user_id");
            return;
        }

        // Validate sort column against whitelist
        Set<String> allowedCols = Set.of("username", "email", "created_at", "last_login");
        if (sortCol == null || !allowedCols.contains(sortCol)) {
            sortCol = "created_at";
        }

        // Validate sort direction - developer believes this is safe since
        // it's constrained to short strings and used after ORDER BY
        if (sortDir == null) {
            sortDir = "ASC";
        }
        // Normalize: trim whitespace, limit length to prevent abuse
        sortDir = sortDir.trim();
        if (sortDir.length() > 200) {
            sortDir = "ASC";
        }

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass)) {
            // user_id is validated numeric, sortCol is whitelisted
            // sortDir cannot be parameterized in ORDER BY clause per JDBC spec
            String sql = "SELECT user_id, username, email, created_at, last_login " +
                         "FROM user_profiles WHERE department_id = (" +
                         "SELECT department_id FROM users WHERE user_id = " + userId + ") " +
                         "ORDER BY " + sortCol + " " + sortDir;

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(sql)) {
                JSONArray results = new JSONArray();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    row.put("user_id", rs.getInt("user_id"));
                    row.put("username", rs.getString("username"));
                    row.put("email", rs.getString("email"));
                    row.put("created_at", rs.getString("created_at"));
                    row.put("last_login", rs.getString("last_login"));
                    results.put(row);
                }
                resp.getWriter().write(results.toString());
            }
        } catch (SQLException e) {
            // Log full error for debugging - includes query for troubleshooting
            System.err.println("SQL Error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Profile update endpoint - uses parameterized queries
        String userId = req.getParameter("user_id");
        String email = req.getParameter("email");
        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400);
            return;
        }
        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass)) {
            PreparedStatement ps = conn.prepareStatement(
                "UPDATE user_profiles SET email = ? WHERE user_id = ?");
            ps.setString(1, email);
            ps.setInt(2, Integer.parseInt(userId));
            ps.executeUpdate();
            resp.setStatus(200);
        } catch (SQLException e) {
            resp.sendError(500);
        }
    }
}
